UPDATE lessons SET title='Year 3, Week 13, Lesson 2: Healthy snack challenge', data=json_patch(data,'{"child_mission":"A healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus, yoghurt, cheese and crackers, or plain popcorn. A good snack is easy to prepare, safe for everyone including people with allergies, and affordable. To design a snack, compare options with a short list of criteria: food groups, sugar and salt, cost and safety.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nCompare two snacks using the criteria: (A) carrot sticks and hummus, (B) a chocolate bar. Which is better for an everyday snack, and why?\n\nFEEDBACK\nA is better: it gives vegetables and legumes, is low in sugar and gives fibre. B is a sometimes food with high added sugar and fat and few nutrients. Compare with criteria, not only taste.\n\nWATCH FOR\nBelieving a snack is healthy because the packet says ''healthy'' or ''natural''. Read the food groups and the ingredient list, because some labelled snacks are high in sugar.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nDesign a healthy snack for a class of 24 with an allergy-safe plan. Write the ingredients by group, a score using four criteria, a cost estimate and two safety steps for handling food. Prepare it only with an adult and wash hands first.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"A healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus, yoghurt, cheese and crackers, or plain popcorn. A good snack is easy to prepare, safe for everyone including people with allergies, and affordable. To design a snack, compare options with a short list of criteria: food groups, sugar and salt, cost and safety.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-IHW-01"],"parent_notes":"Parent: Marking guidance for the independent task: Design a healthy snack for a class of 24 with an allergy-safe plan. Write the ingredients by group, a score using four criteria, a cost estimate and two safety steps for handling food. Prepare it only with an adult and w Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using a healthy snack on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Believing a snack is healthy because the packet says ''healthy'' or ''natural''.. Correction: A is better: it gives vegetables and legumes, is low in sugar and gives fibre.. Why it helps the audience is stated.\n\nParent: Likely misconception: Believing a snack is healthy because the packet says ''healthy'' or ''natural''. Read the food groups and the ingredient list, because some labelled snacks are high in sugar. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating a healthy snack on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with a healthy snack, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about a healthy snack with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for a healthy snack. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for a healthy snack. The other choices miss a key step or use a common mistake.","options":["A is better: it gives vegetables and legumes, is low in sugar and gives fibre","Believing a snack is healthy because the packet says ''healthy'' or ''natural''","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Compare two snacks using the criteria: (A) carrot sticks and hummus, (B) a chocolate bar. Which is better for an everyday snack, and why?","type":"multiple_choice"},{"correct_index":1,"explanation":"This is the misconception to avoid for a healthy snack; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Careful use of criteria and explain why it matters with clear evidence","Believing a snack is healthy because the packet says ''healthy'' or ''natural''","A healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus","A is better: it gives vegetables and legumes, is low in sugar and gives fibre"],"question":"Which statement is a common mistake when working with a healthy snack?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and a named criteria and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Believing a snack is healthy because the packet says ''healthy'' or ''natural''","Name criteria and explain why it matters only, without linking it to a healthy snack","Apply a healthy snack to new material and name the criteria and explain why it matters used","Repeat the worked example wording with no new evidence"],"question":"Which response best applies a healthy snack with new evidence?","type":"multiple_choice"},{"correct_index":0,"explanation":"The stronger choice uses safe, healthy or respectful choices appropriately for this lesson on a healthy snack. The other choices miss a key step or use a common mistake.","options":["A is better: it gives vegetables and legumes, is low in sugar and gives fibre","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Believing a snack is healthy because the packet says ''healthy'' or ''natural''"],"question":"Which response best uses safe, healthy or respectful choices for a healthy snack?","type":"multiple_choice"},{"correct_index":0,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Name a body cue, safety rule or wellbeing strategy and say how it helps with a healthy snack","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Believing a snack is healthy because the packet says ''healthy'' or ''natural''"],"question":"Which evidence move best supports a claim about a healthy snack?","type":"multiple_choice"},{"correct_index":3,"explanation":"The stronger choice matches the taught idea (A healthy snack gives energy between meals and comes from the five food) with concrete detail. The other choices miss a key step or use a common mistake.","options":["Believing a snack is healthy because the packet says ''healthy'' or ''natural''","Choose the fastest option even when it ignores safety","Use a put-down and call it honesty","Example snack plan: apple slices with plain yoghurt dip"],"question":"Which choice best applies this lesson idea about a healthy snack?","type":"multiple_choice"},{"correct_index":3,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Invent missing details to make the answer sound complete","Ignore safety or cultural protocols to finish faster","Treat every claim as equally reliable without checking a source or cue","Check safety and fairness, include others, and explain the healthier choice"],"question":"Which action keeps safe, healthy or respectful choices accurate for a healthy snack?","type":"multiple_choice"},{"correct_index":2,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["Believing a snack is healthy because the packet says ''healthy'' or ''natural''","Name criteria and explain why it matters only, with no linked example","Design a healthy snack for a class of 24 with an allergy-safe plan","Retype the worked example with no new example"],"question":"Which independent response best applies a healthy snack to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about a healthy snack with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating a healthy snack on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using a healthy snack on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for a healthy snack. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with a healthy snack, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Believing a snack is healthy because the packet says ''healthy'' or ''natural''.. Correction: A is better: it gives vegetables and legumes, is low in sugar and gives fibre.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y3-w13-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise a healthy snack.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Healthy, Safe and Active Lifestyles","success_criteria":["I can use a healthy snack with a specific example from this lesson.","I can identify criteria and explain why it matters.","I can practise allergy-safe independently on a new prompt.","I can notice cost needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":2,"explanation":"A healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus, yoghurt, cheese and crackers, or plain popcorn.","options":["A guess with no reason","A choice unrelated to safety, health or respect","A healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about a healthy snack with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample snack plan: apple slices with plain yoghurt dip. Food groups: fruit and milk (yes). Added sugar: low. Salt: low. Cost: cheap. Allergies: nut-free. Score: 5 out of 5. Rejected: a packet of lollies (no food group, high sugar).\n\nTRY FIRST\nCompare two snacks using the criteria: (A) carrot sticks and hummus, (B) a chocolate bar. Which is better for an everyday snack, and why?\n\nFEEDBACK\nA is better: it gives vegetables and legumes, is low in sugar and gives fibre. B is a sometimes food with high added sugar and fat and few nutrients. Compare with criteria, not only taste.","explain":"A healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus, yoghurt, cheese and crackers, or plain popcorn. A good snack is easy to prepare, safe for everyone including people with allergies, and affordable. To design a snack, compare options with a short list of criteria: food groups, sugar and salt, cost and safety.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Believing a snack is healthy because the packet says ''healthy'' or ''natural''. Read the food groups and the ingredient list, because some labelled snacks are high in sugar. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Comparing two snacks.","caption":"Compare with criteria.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Hummus</text><text x=\"28\" y=\"78\">vegetables and legumes</text><text x=\"358\" y=\"42\">Chocolate</text><text x=\"358\" y=\"78\">sugar and fat</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Example snack plan: apple slices with plain yoghurt dip. Food groups: fruit and milk (yes). Added sugar: low. Salt: low. Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Example snack plan: apple slices with plain yoghurt dip. Food groups: fruit and milk (yes). Added sugar: low. Salt: low. Then write your own reasons."}}]},{"check":{"correct_index":0,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.","options":["Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about a healthy snack with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample snack plan: apple slices with plain yoghurt dip. Food groups: fruit and milk (yes). Added sugar: low. Salt: low. Cost: cheap. Allergies: nut-free. Score: 5 out of 5. Rejected: a packet of lollies (no food group, high sugar). Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"A snack score table.","caption":"Score every snack.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Criteria</text><text x=\"28\" y=\"78\">groups, sugar, cost, safety</text><text x=\"358\" y=\"42\">Score</text><text x=\"358\" y=\"78\">5 out of 5</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison.","options":["An answer copied without understanding","Use an intentionally unsafe or unhelpful choice as a comparison","A guess with no reason","A choice unrelated to safety, health or respect"],"question":"Which choice best applies this lesson idea about a healthy snack with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nBelieving a snack is healthy because the packet says ''healthy'' or ''natural''. Read the food groups and the ingredient list, because some labelled snacks are high in sugar. Here is a more helpful example: Example snack plan: apple slices with plain yoghurt dip. Food groups: fruit and milk (yes). Added sugar: low. Salt: low. Cost: cheap. Allergies: nut-free. Score: 5 out of 5. Rejected: a packet of lollies (no food group, high sugar).\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nA is better: it gives vegetables and legumes, is low in sugar and gives fibre. B is a sometimes food with high added sugar and fat and few nutrients. Compare with criteria, not only taste.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. Believing a snack is healthy because the packet says ''healthy'' or ''natural''. Read the food groups and the ingredient list, because some labelled snacks are high in sugar. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":0,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example.","options":["Use the same PDHPE idea in a new place, game or situation, not a copy of the example","A choice unrelated to safety, health or respect","An answer copied without understanding","A guess with no reason"],"question":"Which choice best applies this lesson idea about a healthy snack with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nA healthy snack gives energy between meals and comes from the five food groups, such as fruit, vegetables with hummus, yoghurt, cheese and crackers, or plain popcorn. A good snack is easy to prepare, safe for everyone including people with allergies, and affordable. To design a snack, compare options with a short list of criteria: food groups, sugar and salt, cost and safety. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 3, Week 13, Lesson 2: Healthy snack challenge","unit_number":3,"unit_title":"Healthy food and nutrition","week":13,"week_in_unit":3,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample snack plan: apple slices with plain yoghurt dip. Food groups: fruit and milk (yes). Added sugar: low. Salt: low. Cost: cheap. Allergies: nut-free. Score: 5 out of 5. Rejected: a packet of lollies (no food group, high sugar).\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Comparing two snacks.","caption":"Compare with criteria.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Hummus</text><text x=\"28\" y=\"78\">vegetables and legumes</text><text x=\"358\" y=\"42\">Chocolate</text><text x=\"358\" y=\"78\">sugar and fat</text></g></svg>"},{"alt":"A snack score table.","caption":"Score every snack.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Criteria</text><text x=\"28\" y=\"78\">groups, sugar, cost, safety</text><text x=\"358\" y=\"42\">Score</text><text x=\"358\" y=\"78\">5 out of 5</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-pdhpe-y3-w13-l2' AND family_id IS NULL;
